PRAGMA foreign_keys = ON;

CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE github_installations (id INTEGER PRIMARY KEY, github_installation_id INTEGER NOT NULL UNIQUE, account_login TEXT NOT NULL, account_type TEXT NOT NULL, suspended_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE repositories (id INTEGER PRIMARY KEY, github_repository_id INTEGER NOT NULL UNIQUE, installation_id INTEGER NOT NULL REFERENCES github_installations(id) ON DELETE CASCADE, owner TEXT NOT NULL, name TEXT NOT NULL, full_name TEXT NOT NULL UNIQUE, visibility TEXT NOT NULL, default_branch TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, monitored INTEGER NOT NULL DEFAULT 1, open_pr_count INTEGER NOT NULL DEFAULT 0, open_issue_count INTEGER NOT NULL DEFAULT 0, last_activity_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE repository_settings (repository_id INTEGER PRIMARY KEY REFERENCES repositories(id) ON DELETE CASCADE, pr_review_enabled INTEGER NOT NULL DEFAULT 1, issue_automation_enabled INTEGER NOT NULL DEFAULT 1, security_scan_enabled INTEGER NOT NULL DEFAULT 1, auto_labeling_enabled INTEGER NOT NULL DEFAULT 1, require_publish_approval INTEGER NOT NULL DEFAULT 0, ai_provider_override TEXT, excluded_paths TEXT NOT NULL DEFAULT '["dist/**","vendor/**","*.lock"]', max_file_size INTEGER NOT NULL DEFAULT 100000, review_instructions TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE webhook_deliveries (id INTEGER PRIMARY KEY, delivery_id TEXT NOT NULL UNIQUE, event_name TEXT NOT NULL, action TEXT, status TEXT NOT NULL DEFAULT 'queued', error_message TEXT, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TEXT);
CREATE TABLE pull_requests (id INTEGER PRIMARY KEY, repository_id INTEGER NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, github_pr_id INTEGER NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, author TEXT NOT NULL, state TEXT NOT NULL, head_sha TEXT NOT NULL, base_branch TEXT NOT NULL, html_url TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(repository_id, number));
CREATE TABLE pull_request_reviews (id INTEGER PRIMARY KEY, pull_request_id INTEGER NOT NULL REFERENCES pull_requests(id) ON DELETE CASCADE, repository_id INTEGER NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, pr_number INTEGER NOT NULL, commit_sha TEXT NOT NULL, status TEXT NOT NULL, risk_level TEXT NOT NULL, provider TEXT NOT NULL, summary TEXT NOT NULL, recommendation TEXT NOT NULL, github_comment_id INTEGER, published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(repository_id, pr_number, commit_sha));
CREATE TABLE review_findings (id INTEGER PRIMARY KEY, review_id INTEGER NOT NULL REFERENCES pull_request_reviews(id) ON DELETE CASCADE, category TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, file_path TEXT, line INTEGER, confirmed INTEGER NOT NULL DEFAULT 0, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(review_id, fingerprint));
CREATE TABLE issues (id INTEGER PRIMARY KEY, repository_id INTEGER NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, github_issue_id INTEGER NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, author TEXT NOT NULL, body TEXT, state TEXT NOT NULL, category TEXT, spam_score REAL NOT NULL DEFAULT 0, html_url TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(repository_id, number));
CREATE TABLE issue_replies (id INTEGER PRIMARY KEY, issue_id INTEGER NOT NULL REFERENCES issues(id) ON DELETE CASCADE, body TEXT NOT NULL, status TEXT NOT NULL, github_comment_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE security_findings (id INTEGER PRIMARY KEY, repository_id INTEGER NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, review_id INTEGER REFERENCES pull_request_reviews(id) ON DELETE SET NULL, severity TEXT NOT NULL, finding_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, file_path TEXT, status TEXT NOT NULL DEFAULT 'open', confirmed INTEGER NOT NULL DEFAULT 0, fingerprint TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workflow_runs (id INTEGER PRIMARY KEY, repository_id INTEGER NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, github_run_id INTEGER NOT NULL UNIQUE, name TEXT NOT NULL, status TEXT NOT NULL, conclusion TEXT, branch TEXT, commit_sha TEXT NOT NULL, html_url TEXT NOT NULL, started_at TEXT, completed_at TEXT, duration_ms INTEGER, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE automation_rules (id INTEGER PRIMARY KEY, repository_id INTEGER REFERENCES repositories(id) ON DELETE CASCADE, event_type TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, config TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activity_logs (id INTEGER PRIMARY KEY, repository_id INTEGER REFERENCES repositories(id) ON DELETE SET NULL, event_type TEXT NOT NULL, actor TEXT, description TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_provider_settings (id INTEGER PRIMARY KEY CHECK (id = 1), enabled INTEGER NOT NULL DEFAULT 0, provider TEXT NOT NULL DEFAULT 'rule-based', model TEXT, max_input_size INTEGER NOT NULL DEFAULT 50000, max_output_tokens INTEGER NOT NULL DEFAULT 2048, temperature REAL NOT NULL DEFAULT 0.2, private_code_external_enabled INTEGER NOT NULL DEFAULT 0, review_instructions TEXT, issue_instructions TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX idx_repositories_installation ON repositories(installation_id);
CREATE INDEX idx_prs_repository_state ON pull_requests(repository_id, state);
CREATE INDEX idx_reviews_pr_created ON pull_request_reviews(pull_request_id, created_at DESC);
CREATE INDEX idx_issues_repository_state ON issues(repository_id, state);
CREATE INDEX idx_security_status_severity ON security_findings(status, severity);
CREATE INDEX idx_workflows_status ON workflow_runs(status, conclusion);
CREATE INDEX idx_activity_created ON activity_logs(created_at DESC);
CREATE INDEX idx_sessions_expires ON admin_sessions(expires_at);
